PRAGMA foreign_keys=ON;

CREATE TABLE IF NOT EXISTS planning_years (id INTEGER PRIMARY KEY AUTOINCREMENT, year INTEGER UNIQUE NOT NULL, label TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', start_date TEXT, end_date TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS org_units (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER, unit_type TEXT NOT NULL, name TEXT NOT NULL, code TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(parent_id) REFERENCES org_units(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INTEGER NOT NULL, module TEXT NOT NULL, action TEXT NOT NULL, PRIMARY KEY(role_id,module,action), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, role_id INTEGER NOT NULL, primary_org_unit_id INTEGER, employee_id INTEGER, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(primary_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS user_module_access (user_id INTEGER NOT NULL, module TEXT NOT NULL, PRIMARY KEY(user_id,module), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS manager_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, org_unit_id INTEGER NOT NULL, authority TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE CASCADE, UNIQUE(user_id,org_unit_id,authority));
CREATE TABLE IF NOT EXISTS employees (id INTEGER PRIMARY KEY AUTOINCREMENT, employee_no TEXT UNIQUE, full_name TEXT NOT NULL, job_title TEXT, org_unit_id INTEGER, email TEXT, phone TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS strategic_plans (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, start_year INTEGER, end_year INTEGER, status TEXT NOT NULL DEFAULT 'draft', approval_status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS strategic_themes (id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER, code TEXT, name TEXT NOT NULL, description TEXT, active INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(plan_id) REFERENCES strategic_plans(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS strategic_results (id INTEGER PRIMARY KEY AUTOINCREMENT, theme_id INTEGER NOT NULL, code TEXT, name TEXT NOT NULL, description TEXT, FOREIGN KEY(theme_id) REFERENCES strategic_themes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS goals (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, result_id INTEGER, code TEXT, name TEXT NOT NULL, description TEXT, weight REAL NOT NULL DEFAULT 1, approval_status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(result_id) REFERENCES strategic_results(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS objectives (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, goal_id INTEGER NOT NULL, code TEXT, name TEXT NOT NULL, description TEXT, target_value REAL, unit TEXT, baseline_value REAL, direction TEXT NOT NULL DEFAULT 'higher_is_better', weight REAL NOT NULL DEFAULT 1, approval_status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(goal_id) REFERENCES goals(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS kpis (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE, name TEXT NOT NULL, area TEXT, definition TEXT, formula TEXT, unit TEXT, frequency TEXT DEFAULT 'quarterly', direction TEXT NOT NULL DEFAULT 'higher_is_better', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS kpi_plans (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, kpi_id INTEGER NOT NULL, objective_id INTEGER, org_unit_id INTEGER, owner_employee_id INTEGER, baseline_value REAL, annual_target REAL, q1_target REAL, q2_target REAL, q3_target REAL, q4_target REAL, weight REAL NOT NULL DEFAULT 1, approval_status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(kpi_id) REFERENCES kpis(id) ON DELETE CASCADE, FOREIGN KEY(objective_id) REFERENCES objectives(id) ON DELETE SET NULL, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(owner_employee_id) REFERENCES employees(id) ON DELETE SET NULL, UNIQUE(year_id,kpi_id,org_unit_id));
CREATE TABLE IF NOT EXISTS kpi_actuals (id INTEGER PRIMARY KEY AUTOINCREMENT, kpi_plan_id INTEGER NOT NULL, period_type TEXT NOT NULL, period_key TEXT NOT NULL, actual_value REAL, comment TEXT, evidence TEXT, submitted_by INTEGER, verified_by INTEGER, approval_status TEXT NOT NULL DEFAULT 'draft', submitted_at TEXT, verified_at TEXT, FOREIGN KEY(kpi_plan_id) REFERENCES kpi_plans(id) ON DELETE CASCADE, FOREIGN KEY(submitted_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(verified_by) REFERENCES users(id) ON DELETE SET NULL, UNIQUE(kpi_plan_id,period_type,period_key));

CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, code TEXT, name TEXT NOT NULL, location TEXT, description TEXT, org_unit_id INTEGER, manager_employee_id INTEGER, planned_budget REAL NOT NULL DEFAULT 0, actual_spend REAL NOT NULL DEFAULT 0, physical_progress REAL NOT NULL DEFAULT 0, financial_progress REAL NOT NULL DEFAULT 0, start_date TEXT, end_date TEXT, status TEXT NOT NULL DEFAULT 'planned', approval_status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(manager_employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS project_milestones (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, name TEXT NOT NULL, planned_date TEXT, actual_date TEXT, progress REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activities (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, objective_id INTEGER, project_id INTEGER, org_unit_id INTEGER, branch_org_unit_id INTEGER, employee_id INTEGER, code TEXT, title TEXT NOT NULL, description TEXT, quarter TEXT, start_date TEXT, due_date TEXT, progress REAL NOT NULL DEFAULT 0, implementation_status TEXT NOT NULL DEFAULT 'not_started', approval_status TEXT NOT NULL DEFAULT 'draft', budget REAL NOT NULL DEFAULT 0, weight REAL NOT NULL DEFAULT 1, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(objective_id) REFERENCES objectives(id) ON DELETE SET NULL, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(branch_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS task_updates (id INTEGER PRIMARY KEY AUTOINCREMENT, activity_id INTEGER NOT NULL, update_date TEXT NOT NULL, progress REAL NOT NULL DEFAULT 0, note TEXT, submitted_by INTEGER, evidence TEXT, FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE CASCADE, FOREIGN KEY(submitted_by) REFERENCES users(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS annual_plan_allocations (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, org_unit_id INTEGER, name TEXT NOT NULL, allocation_amount REAL NOT NULL DEFAULT 0, notes TEXT, approval_status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS budgets (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, plan_allocation_id INTEGER, org_unit_id INTEGER, category TEXT NOT NULL, planned_amount REAL NOT NULL DEFAULT 0, revised_amount REAL NOT NULL DEFAULT 0, approval_status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(plan_allocation_id) REFERENCES annual_plan_allocations(id) ON DELETE SET NULL, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS budget_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, budget_id INTEGER, org_unit_id INTEGER, activity_id INTEGER, request_date TEXT NOT NULL, purpose TEXT NOT NULL, requested_amount REAL NOT NULL DEFAULT 0, approved_amount REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', approval_status TEXT NOT NULL DEFAULT 'draft', requested_by INTEGER, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(budget_id) REFERENCES budgets(id) ON DELETE SET NULL, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE SET NULL, FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS budget_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, budget_id INTEGER NOT NULL, line_name TEXT NOT NULL, planned_amount REAL NOT NULL DEFAULT 0, revised_amount REAL NOT NULL DEFAULT 0, FOREIGN KEY(budget_id) REFERENCES budgets(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS finance_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, entry_type TEXT NOT NULL, parent_id INTEGER, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(parent_id) REFERENCES finance_categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS finance_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, entry_date TEXT NOT NULL, category_id INTEGER, category TEXT, entry_type TEXT NOT NULL, amount REAL NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'ETB', description TEXT, reference_no TEXT, org_unit_id INTEGER, approval_status TEXT NOT NULL DEFAULT 'draft', entered_by INTEGER, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES finance_categories(id) ON DELETE SET NULL, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(entered_by) REFERENCES users(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS risks (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, category TEXT NOT NULL, title TEXT NOT NULL, description TEXT, probability INTEGER NOT NULL DEFAULT 1, impact INTEGER NOT NULL DEFAULT 1, level TEXT NOT NULL DEFAULT 'Low', owner_org_unit_id INTEGER, mitigation TEXT, contingency TEXT, action TEXT, due_date TEXT, status TEXT NOT NULL DEFAULT 'open', residual_score INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(owner_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS risk_reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, risk_id INTEGER NOT NULL, review_date TEXT NOT NULL, residual_score INTEGER, note TEXT, reviewed_by INTEGER, FOREIGN KEY(risk_id) REFERENCES risks(id) ON DELETE CASCADE, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS compliance_requirements (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, group_name TEXT NOT NULL, item TEXT NOT NULL, unit TEXT, annual_target REAL NOT NULL DEFAULT 0, owner_org_unit_id INTEGER, due_date TEXT, required_evidence TEXT, status TEXT NOT NULL DEFAULT 'open', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(owner_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS compliance_records (id INTEGER PRIMARY KEY AUTOINCREMENT, requirement_id INTEGER NOT NULL, period_key TEXT NOT NULL, actual_value REAL NOT NULL DEFAULT 0, evidence TEXT, verified_by INTEGER, approval_status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(requirement_id) REFERENCES compliance_requirements(id) ON DELETE CASCADE, FOREIGN KEY(verified_by) REFERENCES users(id) ON DELETE SET NULL, UNIQUE(requirement_id,period_key));

CREATE TABLE IF NOT EXISTS monitoring_visits (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, org_unit_id INTEGER, visit_date TEXT NOT NULL, team TEXT, objective TEXT, summary TEXT, findings TEXT, recommendations TEXT, status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS evaluations (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, scope_type TEXT NOT NULL, scope_id INTEGER, relevance REAL DEFAULT 0, effectiveness REAL DEFAULT 0, efficiency REAL DEFAULT 0, impact REAL DEFAULT 0, sustainability REAL DEFAULT 0, overall_score REAL DEFAULT 0, lessons TEXT, recommendations TEXT, evaluator_id INTEGER, status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(evaluator_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS corrective_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, source_type TEXT NOT NULL, source_id INTEGER, title TEXT NOT NULL, description TEXT, owner_org_unit_id INTEGER, due_date TEXT, priority TEXT NOT NULL DEFAULT 'Medium', status TEXT NOT NULL DEFAULT 'open', completion REAL NOT NULL DEFAULT 0, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(owner_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS management_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, owner_org_unit_id INTEGER, due_date TEXT, priority TEXT NOT NULL DEFAULT 'Medium', status TEXT NOT NULL DEFAULT 'open', completion REAL NOT NULL DEFAULT 0, created_by INTEGER, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(owner_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS audits (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, audit_type TEXT NOT NULL, title TEXT NOT NULL, org_unit_id INTEGER, planned_date TEXT, actual_date TEXT, status TEXT NOT NULL DEFAULT 'planned', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS audit_findings (id INTEGER PRIMARY KEY AUTOINCREMENT, audit_id INTEGER NOT NULL, finding TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'Medium', recommendation TEXT, responsible_org_unit_id INTEGER, due_date TEXT, status TEXT NOT NULL DEFAULT 'open', FOREIGN KEY(audit_id) REFERENCES audits(id) ON DELETE CASCADE, FOREIGN KEY(responsible_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS procurements (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, org_unit_id INTEGER, request_no TEXT, item TEXT NOT NULL, category TEXT, estimated_amount REAL NOT NULL DEFAULT 0, approved_amount REAL NOT NULL DEFAULT 0, supplier TEXT, request_date TEXT, due_date TEXT, status TEXT NOT NULL DEFAULT 'draft', approval_status TEXT NOT NULL DEFAULT 'draft', requested_by INTEGER, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS hr_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, action_type TEXT NOT NULL, title TEXT NOT NULL, employee_id INTEGER, org_unit_id INTEGER, target_value REAL NOT NULL DEFAULT 0, actual_value REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'planned', notes TEXT, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS trainings (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, title TEXT NOT NULL, provider TEXT, planned_date TEXT, participants_target INTEGER NOT NULL DEFAULT 0, participants_actual INTEGER NOT NULL DEFAULT 0, budget REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'planned', org_unit_id INTEGER, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS assets (id INTEGER PRIMARY KEY AUTOINCREMENT, asset_no TEXT UNIQUE, asset_name TEXT NOT NULL, category TEXT, acquisition_date TEXT, acquisition_cost REAL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', org_unit_id INTEGER, custodian_employee_id INTEGER, location TEXT, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(custodian_employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS properties (id INTEGER PRIMARY KEY AUTOINCREMENT, property_no TEXT UNIQUE, name TEXT NOT NULL, property_type TEXT, location TEXT, area REAL, ownership_status TEXT, utilization_status TEXT, annual_income REAL DEFAULT 0, notes TEXT);

CREATE TABLE IF NOT EXISTS tourism_records (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, branch_org_unit_id INTEGER, record_date TEXT NOT NULL, domestic_visitors INTEGER DEFAULT 0, international_visitors INTEGER DEFAULT 0, room_nights_available INTEGER DEFAULT 0, room_nights_occupied INTEGER DEFAULT 0, revenue REAL DEFAULT 0, satisfaction REAL DEFAULT 0, stay_hours REAL DEFAULT 0, notes TEXT, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(branch_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS stakeholders (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT, influence TEXT, interest TEXT, contact TEXT, relationship_status TEXT DEFAULT 'active', notes TEXT);
CREATE TABLE IF NOT EXISTS legal_matters (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, matter_type TEXT NOT NULL, title TEXT NOT NULL, counterparty TEXT, value REAL DEFAULT 0, responsible_employee_id INTEGER, status TEXT DEFAULT 'open', next_action TEXT, due_date TEXT, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(responsible_employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS research_studies (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, title TEXT NOT NULL, objective TEXT, responsible_org_unit_id INTEGER, budget REAL DEFAULT 0, status TEXT DEFAULT 'planned', findings TEXT, recommendations TEXT, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(responsible_org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL);

CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, report_type TEXT NOT NULL, period_key TEXT NOT NULL, title TEXT NOT NULL, summary TEXT, status TEXT NOT NULL DEFAULT 'draft', submitted_by INTEGER, approved_by INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(submitted_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS approvals (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER, entity_type TEXT NOT NULL, entity_id INTEGER NOT NULL, step_no INTEGER NOT NULL, step_name TEXT NOT NULL, required_role TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', requested_by INTEGER, decided_by INTEGER, decision TEXT, comment TEXT, requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, decided_at TEXT, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE SET NULL, FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, action TEXT NOT NULL, entity_type TEXT, entity_id INTEGER, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS attachments (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_type TEXT NOT NULL, entity_id INTEGER NOT NULL, filename TEXT NOT NULL, note TEXT, created_by INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS annual_plan_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, version_no INTEGER NOT NULL, reason TEXT, created_by INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'draft', FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);

-- Admin-configurable system settings
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY AUTOINCREMENT, category TEXT NOT NULL, key TEXT NOT NULL, value TEXT, value_type TEXT NOT NULL DEFAULT 'text', label TEXT NOT NULL, description TEXT, active INTEGER NOT NULL DEFAULT 1, updated_by INTEGER, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL, UNIQUE(category, key));

-- Employee evaluations tied to plans and execution
CREATE TABLE IF NOT EXISTS employee_evaluations (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, employee_id INTEGER NOT NULL, org_unit_id INTEGER, evaluator_id INTEGER, plan_score REAL DEFAULT 0, execution_score REAL DEFAULT 0, overall_score REAL DEFAULT 0, plan_notes TEXT, execution_notes TEXT, strengths TEXT, areas_for_improvement TEXT, targets_next_period TEXT, status TEXT NOT NULL DEFAULT 'draft', approval_status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(org_unit_id) REFERENCES org_units(id) ON DELETE SET NULL, FOREIGN KEY(evaluator_id) REFERENCES users(id) ON DELETE SET NULL);

-- Evaluation criteria (configurable by admin)
CREATE TABLE IF NOT EXISTS evaluation_criteria (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, weight REAL NOT NULL DEFAULT 1, category TEXT NOT NULL DEFAULT 'general', active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);

-- Period definitions for flexible reporting
CREATE TABLE IF NOT EXISTS period_definitions (id INTEGER PRIMARY KEY AUTOINCREMENT, year_id INTEGER NOT NULL, period_type TEXT NOT NULL, period_key TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, label TEXT, active INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(year_id) REFERENCES planning_years(id) ON DELETE CASCADE, UNIQUE(year_id, period_type, period_key));
